<h2>Calculate property brokerage or commission</h2><p class="lead">Estimate total brokerage/commission, tax on the fee if applicable, and net proceeds before other closing costs.</p><div class="notice">This calculator does not assume a legally mandated or market-standard commission. Use the written brokerage agreement and applicable tax treatment.</div><div class="form-grid"><div class="field"><label for="price">Property transaction value</label><input id="price" type="number" value="5000000" min="0" step="any"></div><div class="field"><label for="rate">Commission rate (%)</label><input id="rate" type="number" value="2" min="0" step="any"></div><div class="field"><label for="tax">Tax on commission (%)</label><input id="tax" type="number" value="0" min="0" step="any"></div><div class="field"><label for="split">Your share of commission (%)</label><input id="split" type="number" value="100" min="0" max="100" step="any"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Gross commission</span><strong id="gross">—</strong></div><div class="metric"><span>Tax on commission</span><strong id="taxamt">—</strong></div><div class="metric"><span>Commission incl. tax</span><strong id="total">—</strong></div><div class="metric"><span>Your commission share</span><strong id="share">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('gross').textContent='—';$('taxamt').textContent='—';$('total').textContent='—';$('share').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const p=num('price'),r=num('rate'),tx=num('tax'),sp=num('split');if(!(p>=0&&r>=0&&tx>=0&&sp>=0&&sp<=100))throw 0;const g=p*r/100,t=g*tx/100,tot=g+t,share=g*sp/100;$('gross').textContent=fmt(g,2);$('taxamt').textContent=fmt(t,2);$('total').textContent=fmt(tot,2);$('share').textContent=fmt(share,2);$('note').textContent='Commission structures, taxes, minimum fees and who pays them are contractual and jurisdiction-specific. Enter the actual agreed rates.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
